    // Mock RPC calls on required client proxies
    template <typename Tag, typename Func>
    void mock_rpc([[maybe_unused]] Func&& handler) {
        if constexpr (
            std::is_same_v<Tag, typename App::ports::SupervisorRequired::CalibrateOdometer>
            || std::is_same_v<Tag, ::reaktar::tags::vehicle_supervisor::methods::CalibrateOdometer>
        ) {
            if (auto lease = app_.acquire_supervisorrequired_proxy()) {
                using MethodExpectedRet = decltype(lease->CalibrateOdometer(std::declval<const uint32_t&>()));
                lease->skel_calibrate_odometer_ = [h = std::forward<Func>(handler)](const uint32_t& current_km) -> MethodExpectedRet {
                    return result_adapter<MethodExpectedRet, decltype(h(current_km))>::adapt(
                        h(current_km)
                    );
                };
            }
        }
        else if constexpr (
            std::is_same_v<Tag, typename App::ports::SupervisorRequired::ResetTripMeter>
            || std::is_same_v<Tag, ::reaktar::tags::vehicle_supervisor::methods::ResetTripMeter>
        ) {
            if (auto lease = app_.acquire_supervisorrequired_proxy()) {
                lease->skel_reset_trip_meter_ = std::forward<Func>(handler);
            }
        }
        else if constexpr (
            std::is_same_v<Tag, typename App::ports::SupervisorRequired::SetSpeedLimiter>
            || std::is_same_v<Tag, ::reaktar::tags::vehicle_supervisor::methods::SetSpeedLimiter>
        ) {
            if (auto lease = app_.acquire_supervisorrequired_proxy()) {
                using MethodExpectedRet = decltype(lease->SetSpeedLimiter(std::declval<const float&>(), std::declval<const bool&>()));
                lease->skel_set_speed_limiter_ = [h = std::forward<Func>(handler)](const float& max_kmh, const bool& active) -> MethodExpectedRet {
                    return result_adapter<MethodExpectedRet, decltype(h(max_kmh, active))>::adapt(
                        h(max_kmh, active)
                    );
                };
            }
        }
        else if constexpr (
            std::is_same_v<Tag, typename App::ports::SupervisorRequired::TriggerDiagnostic>
            || std::is_same_v<Tag, ::reaktar::tags::vehicle_supervisor::methods::TriggerDiagnostic>
        ) {
            if (auto lease = app_.acquire_supervisorrequired_proxy()) {
                using MethodExpectedRet = decltype(lease->TriggerDiagnostic(std::declval<const uint32_t&>()));
                lease->skel_trigger_diagnostic_ = [h = std::forward<Func>(handler)](const uint32_t& code) -> MethodExpectedRet {
                    return result_adapter<MethodExpectedRet, decltype(h(code))>::adapt(
                        h(code)
                    );
                };
            }
        }
        else {
            static_assert(!sizeof(Tag*), "reaktar: Unknown RPC method tag for mock_rpc");
        }
    }

